// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests local purge: aged files, verified only, trash expiry
// Flo: temp data folder with real gzip raw files + pack rows > run at a shifted clock > assert where files are
// I/O: temp folder + temp db > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const loca = @import("ru-purg-loca.zig"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig"); const file = @import("st-stor-file.zig"); const civi = @import("ut-date-civi.zig");
const allo = std.testing.allocator;
const DAYZ: i64 = 86400000;
const Rigg = struct { tmpz: std.testing.TmpDir, dirz: []u8, rawd: []u8, dbzz: sqli.Dbzz, aren: std.heap.ArenaAllocator, wall: i64, prng: std.Random.DefaultPrng,
pub fn upzz(self: *Rigg) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); self.rawd = try std.fs.path.join(allo, &.{ self.dirz, "raw" }); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); self.wall = std.Io.Clock.real.now(std.testing.io).toMilliseconds(); self.prng = std.Random.DefaultPrng.init(7); }
pub fn down(self: *Rigg) void { self.aren.deinit(); self.dbzz.close(); allo.free(self.rawd); allo.free(self.dirz); self.tmpz.cleanup(); }
pub fn raws(self: *Rigg, size: usize, vfyz: ?i64) ![]const u8 { const body = try allo.alloc(u8, size); defer allo.free(body); self.prng.random().bytes(body); const sav2 = try file.fileSave(allo, std.testing.io, self.rawd, body); const hexz = try self.aren.allocator().dupe(u8, &sav2.hexz); if (vfyz) |valu| { var insz = try self.dbzz.prep("INSERT INTO pack(hexz,packk,offs,lenz,vfyz) VALUES(?1,'runs/x',0,1,?2);"); defer insz.fini(); try insz.bindText(1, hexz); try insz.bindIntz(2, valu); _ = try insz.step(); } return hexz; }
pub fn lcal(self: *Rigg, capz: u64) loca.Loca { return .{ .iozz = std.testing.io, .dbzz = &self.dbzz, .dirz = self.dirz, .conf = .{}, .capz = capz }; }
pub fn pthz(self: *Rigg, base: []const u8, hexz: []const u8) ![]const u8 { return std.fmt.allocPrint(self.aren.allocator(), "{s}/{s}/{s}/{s}/{s}.gz", .{ self.dirz, base, hexz[0..2], hexz[2..4], hexz }); }
pub fn here(self: *Rigg, path: []const u8) bool { _ = self; _ = std.Io.Dir.cwd().statFile(std.testing.io, path, .{}) catch return false; return true; }
pub fn scal(self: *Rigg, sqlz: [:0]const u8) !i64 { var stmt = try self.dbzz.prep(sqlz); defer stmt.fini(); if (!try stmt.step()) return -1; return stmt.colzIntz(0); } };
const BIGG: u64 = 1 << 30;
test "aged verified files go to the dated trash; unverified ones and unverified rows stay" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const aaaz = try rig3.raws(2000, 5); const bbbz = try rig3.raws(2000, 5); const cccz = try rig3.raws(2000, null); const ddzz = try rig3.raws(2000, 0); var lcal = rig3.lcal(BIGG); const nowz = rig3.wall + 40 * DAYZ; const rslt = try loca.locaRunz(&lcal, rig3.aren.allocator(), nowz); try std.testing.expectEqual(@as(u32, 2), rslt.aged); var dbuf: [8]u8 = undefined; const dayz = civi.civiDayz(nowz, &dbuf); try std.testing.expect(!rig3.here(try rig3.pthz("raw", aaaz))); try std.testing.expect(!rig3.here(try rig3.pthz("raw", bbbz))); try std.testing.expect(rig3.here(try rig3.pthz(try std.fmt.allocPrint(rig3.aren.allocator(), "trash/{s}", .{dayz}), aaaz))); try std.testing.expect(rig3.here(try rig3.pthz("raw", cccz))); try std.testing.expect(rig3.here(try rig3.pthz("raw", ddzz))); try std.testing.expectEqual(loca.Actl.pruned, rslt.act2); }
test "files younger than purg_loca_days stay" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const aaaz = try rig3.raws(2000, 5); var lcal = rig3.lcal(BIGG); const rslt = try loca.locaRunz(&lcal, rig3.aren.allocator(), rig3.wall + 10 * DAYZ); try std.testing.expectEqual(@as(u32, 0), rslt.aged); try std.testing.expect(rig3.here(try rig3.pthz("raw", aaaz))); try std.testing.expectEqual(loca.Actl.none, rslt.act2); }
test "purg_loca_veri off: a pack row is enough, a file with no row still stays" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const cccz = try rig3.raws(2000, null); const ddzz = try rig3.raws(2000, 0); var lcal = rig3.lcal(BIGG); lcal.conf.purg_loca_veri = false; const rslt = try loca.locaRunz(&lcal, rig3.aren.allocator(), rig3.wall + 40 * DAYZ); try std.testing.expectEqual(@as(u32, 1), rslt.aged); try std.testing.expect(rig3.here(try rig3.pthz("raw", cccz))); try std.testing.expect(!rig3.here(try rig3.pthz("raw", ddzz))); }
test "trash days older than purg_tras_days are deleted, recent ones stay" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const nowz = rig3.wall + 40 * DAYZ; var b1zz: [8]u8 = undefined; var b2zz: [8]u8 = undefined; const oldd = try std.fmt.allocPrint(rig3.aren.allocator(), "{s}/trash/{s}/ab/cd", .{ rig3.dirz, civi.civiDayz(nowz - 8 * DAYZ, &b1zz) }); const newd = try std.fmt.allocPrint(rig3.aren.allocator(), "{s}/trash/{s}/ab/cd", .{ rig3.dirz, civi.civiDayz(nowz - 2 * DAYZ, &b2zz) }); const cwdz = std.Io.Dir.cwd(); try cwdz.createDirPath(std.testing.io, oldd); try cwdz.createDirPath(std.testing.io, newd); try cwdz.writeFile(std.testing.io, .{ .sub_path = try std.fmt.allocPrint(rig3.aren.allocator(), "{s}/f.gz", .{oldd}), .data = "old" }); try cwdz.writeFile(std.testing.io, .{ .sub_path = try std.fmt.allocPrint(rig3.aren.allocator(), "{s}/f.gz", .{newd}), .data = "new" }); var lcal = rig3.lcal(BIGG); const rslt = try loca.locaRunz(&lcal, rig3.aren.allocator(), nowz); try std.testing.expectEqual(@as(u32, 1), rslt.tras); try std.testing.expect(!rig3.here(try std.fmt.allocPrint(rig3.aren.allocator(), "{s}/f.gz", .{oldd}))); try std.testing.expect(rig3.here(try std.fmt.allocPrint(rig3.aren.allocator(), "{s}/f.gz", .{newd}))); }
test "purg_tras_days 0 deletes directly, no trash folder appears" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const aaaz = try rig3.raws(2000, 5); var lcal = rig3.lcal(BIGG); lcal.conf.purg_tras_days = 0; const rslt = try loca.locaRunz(&lcal, rig3.aren.allocator(), rig3.wall + 40 * DAYZ); try std.testing.expectEqual(@as(u32, 1), rslt.aged); try std.testing.expect(!rig3.here(try rig3.pthz("raw", aaaz))); const trad = try std.fmt.allocPrint(rig3.aren.allocator(), "{s}/trash", .{rig3.dirz}); try std.testing.expect(!rig3.here(trad)); }
test "pressure: at the high mark the trash is emptied and oldest verified files are deleted down to the low mark" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); for (0..5) |_| _ = try rig3.raws(200000, 5); var b1zz: [8]u8 = undefined; const trad = try std.fmt.allocPrint(rig3.aren.allocator(), "{s}/trash/{s}/ab/cd", .{ rig3.dirz, civi.civiDayz(rig3.wall, &b1zz) }); try std.Io.Dir.cwd().createDirPath(std.testing.io, trad); try std.Io.Dir.cwd().writeFile(std.testing.io, .{ .sub_path = try std.fmt.allocPrint(rig3.aren.allocator(), "{s}/f.gz", .{trad}), .data = "trash bytes" }); const usa0 = try loca.locaUsed(rig3.aren.allocator(), std.testing.io, rig3.dirz); const capz = usa0 * 100 / 92; var lcal = rig3.lcal(capz); const rslt = try loca.locaRunz(&lcal, rig3.aren.allocator(), rig3.wall + DAYZ); try std.testing.expectEqual(loca.Actl.pruned, rslt.act2); try std.testing.expect(rslt.pres >= 2); try std.testing.expect(rslt.used <= capz * 60 / 100); try std.testing.expect(!rig3.here(try std.fmt.allocPrint(rig3.aren.allocator(), "{s}/f.gz", .{trad}))); }
test "pressure with nothing verified: stuck, no file is touched" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); var list: [4][]const u8 = undefined; for (&list) |*slot| slot.* = try rig3.raws(200000, null); const usa0 = try loca.locaUsed(rig3.aren.allocator(), std.testing.io, rig3.dirz); var lcal = rig3.lcal(usa0 * 100 / 92); const rslt = try loca.locaRunz(&lcal, rig3.aren.allocator(), rig3.wall + 40 * DAYZ); try std.testing.expectEqual(loca.Actl.stuck, rslt.act2); try std.testing.expectEqual(@as(u32, 0), rslt.pres); for (list) |hexz| try std.testing.expect(rig3.here(try rig3.pthz("raw", hexz))); }
test "housekeeping prunes old log, finished outbox and dead frontier rows only" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const nowz = rig3.wall + 400 * DAYZ; const oldz = nowz - 200 * DAYZ; const newz = nowz - DAYZ; try rig3.dbzz.exec("INSERT INTO logz(urlz,code,tier,vend,cred,micr,robo,timz,note) VALUES('a',200,1,'',0,0,'',1000,'');"); var ins2 = try rig3.dbzz.prep("INSERT INTO logz(urlz,code,tier,vend,cred,micr,robo,timz,note) VALUES('b',200,1,'',0,0,'',?1,'');"); defer ins2.fini(); try ins2.bindIntz(1, newz); _ = try ins2.step(); try rig3.dbzz.exec("INSERT INTO outb(kind,keyz,stat,tryz,errz,timz) VALUES('file','o1',1,0,'',1000); INSERT INTO outb(kind,keyz,stat,tryz,errz,timz) VALUES('file','o2',0,0,'',1000);"); try rig3.dbzz.exec("INSERT INTO fron(urlz,host,stat,tryz,next,errz,addz) VALUES('f1','h',2,0,0,'',1000); INSERT INTO fron(urlz,host,stat,tryz,next,errz,addz) VALUES('f2','h',1,0,0,'',1000);"); _ = oldz; var lcal = rig3.lcal(BIGG); const rslt = try loca.locaRunz(&lcal, rig3.aren.allocator(), nowz); try std.testing.expectEqual(@as(u32, 1), rslt.logz); try std.testing.expectEqual(@as(u32, 1), rslt.outb); try std.testing.expectEqual(@as(u32, 1), rslt.dead); try std.testing.expectEqual(@as(i64, 1), try rig3.scal("SELECT count(*) FROM logz;")); try std.testing.expectEqual(@as(i64, 1), try rig3.scal("SELECT count(*) FROM outb WHERE stat=0;")); try std.testing.expectEqual(@as(i64, 1), try rig3.scal("SELECT count(*) FROM fron WHERE stat=1;")); try std.testing.expectEqual(@as(i64, 0), try rig3.scal("SELECT count(*) FROM fron WHERE stat=2;")); }
test "dry run counts the plan and changes nothing" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const aaaz = try rig3.raws(2000, 5); try rig3.dbzz.exec("INSERT INTO logz(urlz,code,tier,vend,cred,micr,robo,timz,note) VALUES('a',200,1,'',0,0,'',1000,'');"); var lcal = rig3.lcal(BIGG); lcal.dryz = true; const rslt = try loca.locaRunz(&lcal, rig3.aren.allocator(), rig3.wall + 400 * DAYZ); try std.testing.expect(rslt.plan); try std.testing.expectEqual(@as(u32, 1), rslt.aged); try std.testing.expectEqual(@as(u32, 1), rslt.logz); try std.testing.expect(rig3.here(try rig3.pthz("raw", aaaz))); try std.testing.expectEqual(@as(i64, 1), try rig3.scal("SELECT count(*) FROM logz;")); }
test "disk used is the sum of all file sizes; the hard cap is 95 percent" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const cwdz = std.Io.Dir.cwd(); const subd = try std.fmt.allocPrint(rig3.aren.allocator(), "{s}/zz/yy", .{rig3.dirz}); try cwdz.createDirPath(std.testing.io, subd); const base = try loca.locaUsed(rig3.aren.allocator(), std.testing.io, rig3.dirz); try cwdz.writeFile(std.testing.io, .{ .sub_path = try std.fmt.allocPrint(rig3.aren.allocator(), "{s}/a.bin", .{subd}), .data = "0123456789" }); try cwdz.writeFile(std.testing.io, .{ .sub_path = try std.fmt.allocPrint(rig3.aren.allocator(), "{s}/zz/b.bin", .{rig3.dirz}), .data = "abcde" }); try std.testing.expectEqual(base + 15, try loca.locaUsed(rig3.aren.allocator(), std.testing.io, rig3.dirz)); try std.testing.expect(!loca.fullChek(94, 100)); try std.testing.expect(loca.fullChek(95, 100)); try std.testing.expect(loca.fullChek(200, 100)); try std.testing.expect(!try loca.locaFull(rig3.aren.allocator(), std.testing.io, rig3.dirz, .{})); }
